using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // FIX 1: EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so we must preserve the old property name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // FIX 2: EF Core 9 changed the id format from "EntityType|KeyValue" to just "KeyValue".
        // Existing documents have the old compound format; preserve it for backward compatibility.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

public class Session
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

public class SessionService
{
    // FIX 3: EF Core 9 Cosmos DB provider no longer supports synchronous I/O.
    // All queries and SaveChanges must use async equivalents.

    // BEFORE (EF Core 8 — sync calls that now throw in EF Core 9):
    //   var sessions = db.Sessions.ToList();
    //   var first = db.Sessions.First(s => s.Name == name);
    //   db.SaveChanges();

    // AFTER (EF Core 9 — async equivalents):
    public async Task<List<Session>> GetAllSessionsAsync(CosmosDbContext db)
    {
        return await db.Sessions.ToListAsync();
    }

    public async Task<Session> GetSessionByNameAsync(CosmosDbContext db, string name)
    {
        return await db.Sessions.FirstAsync(s => s.Name == name);
    }

    public async Task AddSessionAsync(CosmosDbContext db, Session session)
    {
        db.Sessions.Add(session);
        await db.SaveChangesAsync();
    }
}

